// validateOrder.ts
export type OrderItem = { sku: string; qty: number };

export function validateOrder(items: OrderItem[]): string | null {
  if (!items.length) return 'empty';
  for (const it of items) {
    if (!it.sku || it.qty < 1) return 'invalid item';
  }
  return null;
}

